package com.eventos.api.security;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import javax.servlet.*; import javax.servlet.http.*; import io.jsonwebtoken.JwtException; import java.io.IOException;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException { String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")) try { Long id=jwt.adminId(h.substring(7)); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,AuthorityUtils.NO_AUTHORITIES)); } catch(JwtException|IllegalArgumentException ignored){} chain.doFilter(req,res); } }
